const Tesseract = require('tesseract.js');
const path = require('path');

const imgPath = '/home/node/.openclaw/media/inbound/7fd872e9-64a1-483e-833f-4b4326eae96e.jpg';

(async () => {
  console.log('Starting OCR...');
  const { data } = await Tesseract.recognize(imgPath, 'chi_sim+chi_tra', {
    logger: m => {
      if (m.status === 'recognizing text') {
        console.log(`Progress: ${Math.round(m.progress * 100)}%`);
      }
    }
  });

  console.log('\n===== RAW OCR TEXT =====');
  console.log(data.text);
  console.log('\n===== WORDS WITH CONFIDENCE =====');
  data.words.forEach(w => {
    console.log(`[${w.confidence.toFixed(0)}%] ${w.text} (${w.bbox.x0},${w.bbox.y0})`);
  });
  console.log(`\nOverall confidence: ${data.confidence}`);
})();

